mapper.delete:
DECLARE
	v_student_no number(20);
BEGIN
	v_student_no := ${studentNo};
BEGIN
	DELETE FROM class_member WHERE member_id = (SELECT member_id
												FROM student_manage
												WHERE student_no = v_student_no
												);
	DELETE FROM student_manage WHERE student_no = v_student_no;
COMMIT;
EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
	RAISE;
  END;
END;

mapper.update:
	{ CALL

		    DECLARE
		      v_student_no NUMBER;
		      v_member_no NUMBER;
		      v_update_count NUMBER;
		      v_insert_count NUMBER;
		    BEGIN
		      SELECT NVL(MAX(member_no), 0)+1 INTO v_member_no FROM class_member;
		    
		      UPDATE student_manage
		      SET
		        member_id = #{memberId},
		        student_email = #{studentEmail},
		        allergy = #{allergy}
		      WHERE student_name = #{studentName}
		  	  AND student_class_no = #{studentClassNo}
		  	  AND class_id = (SELECT class_id
		          			FROM class WHERE class_pw = #{classPw} AND class_id = #{classId});
		        
		      v_update_count := SQL%ROWCOUNT;
		    
		      IF v_update_count = 1 THEN
		        INSERT INTO class_member
		        VALUES(
		        v_member_no
		        ,#{memberId}
		        ,#{classId}
		        );
				IF SQL%ROWCOUNT < 1 THEN
					v_insert_count := 0;
				ELSE
					v_insert_count := SQL%ROWCOUNT;
				END IF;
		#{result, mode=OUT, jdbcType=INTEGER, javaType=Integer} := v_insert_count;
		      END IF;
		      COMMIT;
		    END
		  }
